// components/ReviewCard.jsx

function ReviewCard({ username, text }) {
  return (
    <div style={{
      border: "1px solid #ddd",
      padding: "15px",
      borderRadius: "8px",
      marginBottom: "15px"
    }}>
      <h3>{username}</h3>
      <p>{text}</p>
    </div>
  );
}

export default ReviewCard;
